import{_ as n,a as s}from"./chunks/export-options.DQqHrfEF.js";import{_ as d,C as i,o as l,c as h,a2 as o,j as a,a as t,E as p}from"./chunks/framework.Dx-TCpNt.js";const T=JSON.parse('{"title":"Export","description":"Export turns a chapter of panels and notes into something you can read, print or share: an HTML study document, PNG images for slides, or a project…","frontmatter":{"description":"Export turns a chapter of panels and notes into something you can read, print or share: an HTML study document, PNG images for slides, or a project…"},"headers":[],"relativePath":"guide/export.md","filePath":"guide/export.md","lastUpdated":1794745555000}'),g={name:"guide/export.md"};function c(u,e,m,b,f,x){const r=i("Badge");return l(),h("div",null,[e[4]||(e[4]=o('<h1 id="export" tabindex="-1">Export <a class="header-anchor" href="#export" aria-label="Permalink to &quot;Export&quot;">​</a></h1><p>Export turns a chapter of panels and notes into something you can read, print or share: an HTML study document, PNG images for slides, or a project package for another machine.</p><figure class="shot"><img src="'+n+'" alt="Export dialog with layout templates, scope, languages, image mode and a live preview"><figcaption>The export dialog. The left column configures the document; the right side previews the layout and can be resized by dragging the divider.</figcaption></figure><h2 id="the-problem-it-solves" tabindex="-1">The problem it solves <a class="header-anchor" href="#the-problem-it-solves" aria-label="Permalink to &quot;The problem it solves&quot;">​</a></h2><p>Your notes live inside the app, attached to panels. To review them on a tablet, print them, or drop a comparison into a slide deck, you need a portable artifact that keeps the page image and the matching notes together — without uploading anything.</p><h2 id="opening-the-dialog" tabindex="-1">Opening the dialog <a class="header-anchor" href="#opening-the-dialog" aria-label="Permalink to &quot;Opening the dialog&quot;">​</a></h2><p>Press <code>E</code>, or click <strong>Export</strong> in the top bar. The dialog always exports the page or chapter you are looking at.</p><h2 id="html-export" tabindex="-1">HTML export <a class="header-anchor" href="#html-export" aria-label="Permalink to &quot;HTML export&quot;">​</a></h2><h3 id="title-and-scope" tabindex="-1">Title and scope <a class="header-anchor" href="#title-and-scope" aria-label="Permalink to &quot;Title and scope&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Control</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Title</strong></td><td>Document title, also used for the suggested file name.</td></tr><tr><td><strong>Current page</strong></td><td>Exports only the open page.</td></tr><tr><td><strong>Whole chapter (n pages)</strong></td><td>Exports every annotated page in the chapter.</td></tr><tr><td><strong>Only pages with notes</strong></td><td>Skips pages without notes; useful for a study-notes collection.</td></tr><tr><td><strong>Languages</strong></td><td>Which languages appear in the document.</td></tr></tbody></table><h3 id="image-mode" tabindex="-1">Image mode <a class="header-anchor" href="#image-mode" aria-label="Permalink to &quot;Image mode&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Mode</th><th>Behaviour</th></tr></thead><tbody><tr><td><strong>Sibling <code>.files</code> folder</strong> (default)</td><td>The HTML references images in a folder next to it. Smaller and faster to load. Copy both together.</td></tr><tr><td><strong>Bundle into a single file</strong></td><td>Images are inlined as data URLs. One file to share, but a full chapter can be tens of megabytes.</td></tr></tbody></table><p><strong>Draw panel borders on the original image</strong> overlays the panel rectangles on the exported artwork. This is independent of annotations.</p><p><strong>Only export notes with these tags</strong> filters notes by tag; <strong>Clear filters</strong> removes the selection.</p><h3 id="layout" tabindex="-1">Layout <a class="header-anchor" href="#layout" aria-label="Permalink to &quot;Layout&quot;">​</a></h3><p>Three built-in layout templates:</p><table tabindex="0"><thead><tr><th>Template</th><th>Result</th></tr></thead><tbody><tr><td><strong>Image left, notes right</strong></td><td>Manga page on the left, page and panel notes on the right.</td></tr><tr><td><strong>Image top, notes below</strong></td><td>The image spans the full width and notes unfold underneath.</td></tr><tr><td><strong>Panel comparison</strong></td><td>Each panel shows several languages side by side with its notes.</td></tr></tbody></table><p>Layout templates can be saved under a custom name, exported as JSON and imported again. They live in <code>data/templates/export.json</code>. The layout controls are:</p><table tabindex="0"><thead><tr><th>Control</th><th>Effect</th></tr></thead><tbody><tr><td><strong>Image column width</strong></td><td>Width of the image column, in percent.</td></tr><tr><td><strong>Column gap</strong></td><td>Space between image and notes.</td></tr><tr><td><strong>Font size</strong></td><td>Base font scale for the document.</td></tr><tr><td><strong>Columns per row</strong></td><td>Number of page blocks per row.</td></tr></tbody></table><p>The layout is remembered automatically. You can also drag the divider in the live preview to set the image width.</p><h3 id="generating" tabindex="-1">Generating <a class="header-anchor" href="#generating" aria-label="Permalink to &quot;Generating&quot;">​</a></h3><ol><li>Choose scope, languages, image mode and layout.</li><li>Click <strong>Generate HTML</strong>.</li><li>When it finishes, the dialog reports how many pages were exported and where the file went.</li><li>Use <strong>Open HTML</strong> to open it in the browser, or <strong>Download HTML</strong> to save a copy. With the default image mode, copy the <code>.files</code> folder as well.</li></ol><p>Files are written to the project&#39;s <code>exports/</code> folder. The HTML opens directly from disk.</p><h3 id="printing" tabindex="-1">Printing <a class="header-anchor" href="#printing" aria-label="Permalink to &quot;Printing&quot;">​</a></h3><p>The generated HTML includes print styles: backgrounds are removed, the page width is unconstrained, and page blocks avoid breaking mid-image. Open the file in a browser and use the normal <strong>Print</strong> command to produce a PDF via the browser&#39;s print dialog.</p><div class="tip custom-block"><p class="custom-block-title">Printing to PDF</p><p>Browser &quot;Save as PDF&quot; is the supported way to get a PDF today. A native PDF exporter is not implemented — see <a href="#pdf-and-word">PDF and Word</a>.</p></div><h2 id="png-export" tabindex="-1">PNG export <a class="header-anchor" href="#png-export" aria-label="Permalink to &quot;PNG export&quot;">​</a></h2><p>The <strong>Export PNG</strong> section produces images directly, without a document:</p><table tabindex="0"><thead><tr><th>Mode</th><th>Content</th></tr></thead><tbody><tr><td><strong>Whole page</strong></td><td>The page image with panel borders and annotations.</td></tr><tr><td><strong>Current panel</strong></td><td>The selected panel, cropped and aligned.</td></tr><tr><td><strong>Trilingual collage</strong></td><td>The selected languages placed side by side for the same panel (or the whole page when no panel is selected).</td></tr></tbody></table><p>Options:</p><ul><li><strong>Include annotations (n)</strong> — draws the annotation layer into the PNG. The count shows how many marks will be included.</li><li>Whole-page and current-panel PNG use the <strong>primary (base) language</strong>; the collage uses the selected compare languages.</li><li><strong>Current panel</strong> is disabled until a panel is selected in the workbench.</li></ul><p>PNGs are generated in the browser and land in the browser&#39;s download folder. They paste straight into slides, documents or chat.</p><figure class="shot"><img src="'+s+'" alt="Export dialog with the scope, language chips, image mode, PNG modes and layout sliders"><figcaption>The export dialog with the PNG modes visible. Whole page and current panel use the primary language; the trilingual collage uses the selected languages.</figcaption></figure><h2 id="pdf-and-word" tabindex="-1">PDF and Word <a class="header-anchor" href="#pdf-and-word" aria-label="Permalink to &quot;PDF and Word&quot;">​</a></h2>',34)),a("p",null,[e[0]||(e[0]=t("Native PDF and Word (",-1)),e[1]||(e[1]=a("code",null,".docx",-1)),e[2]||(e[2]=t(") writers are not implemented ",-1)),p(r,{type:"warning",text:"Planned"}),e[3]||(e[3]=t(". The supported route is the HTML export plus the receiving application:",-1))]),e[5]||(e[5]=o('<table tabindex="0"><thead><tr><th>Target</th><th>How to produce it</th></tr></thead><tbody><tr><td><strong>PDF</strong></td><td>Generate the HTML, open it in a browser, then <strong>Print → Save as PDF</strong>. The print styles remove backgrounds, unclamp the page width and avoid breaking inside an image.</td></tr><tr><td><strong>Word</strong></td><td>Generate the HTML and open it in Word, or paste the rendered page into a document. Notes are real HTML, so headings, lists, images and tables survive the paste.</td></tr><tr><td><strong>Plain text / Markdown</strong></td><td>Use <strong>Copy page context</strong> or the <strong>Rendered / Source</strong> toggle on a note; the note body is Markdown.</td></tr></tbody></table><p>Both routes are offline and keep the image/notes pairing. A dedicated exporter would add page-size presets and a style file; that is tracked as planned work, not a hidden option.</p><h2 id="export-templates" tabindex="-1">Export templates <a class="header-anchor" href="#export-templates" aria-label="Permalink to &quot;Export templates&quot;">​</a></h2><p>An export template (<code>.mnexp</code>) stores the layout and style settings so the same look can be reused or shared. Export and import templates through <strong>Exchange files…</strong> in the sidebar. Imported templates are validated and the original file is backed up under <code>data/backups/exchange/</code>.</p><h2 id="common-pitfalls" tabindex="-1">Common pitfalls <a class="header-anchor" href="#common-pitfalls" aria-label="Permalink to &quot;Common pitfalls&quot;">​</a></h2><ul><li><strong>The HTML has broken images.</strong> With the default mode, the <code>.files</code> folder must travel with the HTML. Move them together.</li><li><strong>A single-file export is enormous.</strong> That is expected: every image is inlined. Use the <code>.files</code> mode for a whole chapter.</li><li><strong>A page is missing from the export.</strong> It has no notes and <strong>Only pages with notes</strong> is on, or it has no images in the selected languages.</li><li><strong>Panel borders are not in the PNG.</strong> PNG export uses the annotation toggle; enable <strong>Include annotations</strong>, and remember that panel borders are drawn from the panel rectangles, not from annotations.</li><li><strong>Print output is cropped.</strong> Set the browser print scale to “Fit to page” and enable background graphics only if you need the shading.</li><li><strong>Word ignored the layout.</strong> Paste the rendered HTML rather than the Markdown source; Word keeps HTML tables and images but not the two-column drag width.</li><li><strong>There is no .docx or .pdf button.</strong> Those exporters are planned. Use the HTML plus Print / Word route above.</li><li><strong>The output folder is not writable.</strong> In a packaged desktop build, <code>exports/</code> lives inside the chosen library folder.</li></ul><figure class="shot"><div class="shot-missing"><strong>Screenshot pending: exported HTML and PNG results</strong> A screenshot of the generated HTML in a browser and the three PNG modes side by side will be added here. </div><figcaption>Planned screenshot: exported document and PNG outputs.</figcaption></figure><h2 id="missing-screenshots" tabindex="-1">Missing screenshots <a class="header-anchor" href="#missing-screenshots" aria-label="Permalink to &quot;Missing screenshots&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Figure</th><th>Needed for</th></tr></thead><tbody><tr><td>exported HTML page</td><td>Two-column and stacked layouts</td></tr><tr><td>PNG mode comparison</td><td>Whole page / panel / collage</td></tr><tr><td>export template controls</td><td>Save, import and apply</td></tr></tbody></table><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/KomaYomi-docs/guide/notes">Notes</a> — what ends up in the document.</li><li><a href="/KomaYomi-docs/guide/project-files">Project Files &amp; Formats</a> — exporting the whole project instead.</li><li><a href="/KomaYomi-docs/guide/shortcuts">Keyboard Shortcuts</a> — <code>E</code> opens this dialog.</li></ul>',11))])}const P=d(g,[["render",c]]);export{T as __pageData,P as default};
